#include <functional>
#include <iostream>

struct Foo {
    Foo(int num) : num_(num) {}
    void print_add(int i) const { std::cout << num_ + i << '\n'; }
    int num_;
};

void print_num(int i) { std::cout << i << '\n'; }

struct PrintNum {
    void operator()(int i) const { std::cout << i << '\n'; }
};

int main() {
    // Store a free function
    std::function<void(int)> f_display = print_num;
    f_display(-9);

    // Store a lambda
    std::function<void()> f_display_42 = []() { print_num(42); };
    f_display_42();

    // Store result of std::bind
    std::function<void()> f_display_31337 = std::bind(print_num, 31337);
    f_display_31337();

    // Store call to member function
    std::function<void(const Foo&, int)> f_add_display = &Foo::print_add;
    const Foo foo(314159);
    f_add_display(foo, 1);

    // Store call to data member accessor
    std::function<int(Foo const&)> f_num = &Foo::num_;
    std::cout << "num_: " << f_num(foo) << '\n';

    // Store function object
    std::function<void(int)> f_display_obj = PrintNum();
    f_display_obj(18);

    return 0;
}

// Key properties:
// - Can store any CopyConstructible callable
// - Invoking an empty std::function throws std::bad_function_call
// - Type erasure: hides actual callable type
// - operator bool() checks if target is contained

// Checking if callable:
std::function<void()> f;
if (f) {  // operator bool()
    f();
}

// Recursive lambda using std::function
auto factorial = [](int n) {
    std::function<int(int)> fac = [&](int n) {
        return (n < 2) ? 1 : n * fac(n - 1);
    };
    return fac(n);
};
